package com.townyreborn.staffconnector;
import java.util.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.function.Predicate;import java.nio.file.*;import java.util.concurrent.*;import java.util.logging.Logger;
/** Bounds event memory and transfers minute aggregates on its own worker. */
final class TelemetryBuffer implements AutoCloseable {
 private final Map<String,Map<String,Object>> pending=new LinkedHashMap<>();private final Predicate<Map<String,Object>> sink;private final Path file;private final Logger log;private final ScheduledExecutorService worker;private final Object drain=new Object();private Map<String,Object> flight;private long rejected;
 TelemetryBuffer(Predicate<Map<String,Object>> sink){this(sink,null,null);}
 TelemetryBuffer(Predicate<Map<String,Object>> sink,Path dir,Logger log){this.sink=sink;this.log=log;file=dir==null?null:dir.resolve("telemetry-pending.json");restore();worker=dir==null?null:Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"TR-Statistics");t.setDaemon(true);return t;});if(worker!=null)worker.scheduleWithFixedDelay(()->{try{for(int i=0;i<10 && buffered()>0;i++){int before=buffered();flush();if(before==buffered())break;}}catch(RuntimeException e){log.warning("Statistics retained after "+e.getClass().getSimpleName());}},10,10,TimeUnit.SECONDS);}
 synchronized void record(String plugin,String metric,String dimension,UUID uuid,String name,String world,double value,Map<String,Object> details){if(!Double.isFinite(value)||Math.abs(value)>1e12){rejected++;return;}Instant now=Instant.now();String minute=now.truncatedTo(ChronoUnit.MINUTES).toString();String key=Json.encode(List.of(minute,clean(plugin,96),clean(metric,64),clean(dimension,128),uuid==null?"":uuid.toString(),clean(name,32),clean(world,96)));Map<String,Object> row=pending.get(key);if(row==null){if(pending.size()>=50000){rejected++;return;}row=new LinkedHashMap<>();row.put("minute",minute);row.put("plugin",clean(plugin,96));row.put("metric",clean(metric,64));row.put("dimension",clean(dimension,128));row.put("uuid",uuid==null?"":uuid.toString());row.put("username",clean(name,32));row.put("world",clean(world,96));row.put("value",0d);row.put("count",0L);row.put("min",value);row.put("max",value);row.put("first_at",now.toString());if(details!=null&&!details.isEmpty())row.put("details",new LinkedHashMap<>(details));pending.put(key,row);}if(Math.abs(n(row,"value")+value)>1e12||((Number)row.get("count")).longValue()>=1_000_000){rejected++;return;}row.put("last_at",now.toString());row.put("value",n(row,"value")+value);row.put("count",((Number)row.get("count")).longValue()+1);row.put("min",Math.min(n(row,"min"),value));row.put("max",Math.max(n(row,"max"),value));}
 void flush(){synchronized(drain){synchronized(this){if(flight==null){if(pending.isEmpty())return;List<Map<String,Object>> rows=new ArrayList<>();int bytes=0;Iterator<Map.Entry<String,Map<String,Object>>> it=pending.entrySet().iterator();while(it.hasNext()){var entry=it.next();int len=Json.encode(entry.getValue()).getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(!rows.isEmpty()&&(rows.size()>=120||bytes+len>65000))break;rows.add(entry.getValue());bytes+=len;it.remove();}flight=new LinkedHashMap<>(Map.of("type","telemetry.batch","event_id","telemetry-"+UUID.randomUUID(),"samples",rows));}}if(!save())return;if(sink.test(flight)){synchronized(this){flight=null;}save();}}}
 synchronized int buffered(){return pending.size()+(flight==null?0:((List<?>)flight.get("samples")).size());}synchronized long rejected(){return rejected;}
 private boolean save(){if(file==null)return true;try{Map<String,Object> state;synchronized(this){state=new LinkedHashMap<>();Map<String,Object> snapshot=new LinkedHashMap<>();pending.forEach((k,v)->snapshot.put(k,new LinkedHashMap<>(v)));state.put("pending",snapshot);state.put("flight",flight);state.put("rejected",rejected);}Path tmp=file.resolveSibling(file.getFileName()+".tmp");Files.writeString(tmp,Json.encode(state));try{Files.move(tmp,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,file,StandardCopyOption.REPLACE_EXISTING);}return true;}catch(Exception e){if(log!=null)log.warning("Statistics checkpoint failed: "+e.getClass().getSimpleName());return false;}}
 @SuppressWarnings("unchecked") private void restore(){if(file==null||!Files.isRegularFile(file))return;try{Object v=Json.decode(Files.readString(file));if(v instanceof Map<?,?> m){if(m.get("pending") instanceof Map<?,?> p)p.forEach((k,r)->{if(r instanceof Map<?,?> row)pending.put(String.valueOf(k),(Map<String,Object>)row);});if(m.get("flight") instanceof Map<?,?> f)flight=(Map<String,Object>)f;if(m.get("rejected") instanceof Number r)rejected=r.longValue();}}catch(Exception e){if(log!=null)log.warning("Statistics restore failed: "+e.getClass().getSimpleName());}}
 static String clean(String v,int max){return v==null?"":v.substring(0,Math.min(max,v.length()));}private static double n(Map<?,?> m,String k){return ((Number)m.get(k)).doubleValue();}
 @Override public void close(){if(worker!=null)worker.shutdown();synchronized(drain){for(int i=0;i<500&&buffered()>0;i++){int before=buffered();flush();if(before==buffered())break;}save();}}
}
